import javax.cache.Cache;
import javax.cache.CacheManager;
import javax.cache.Caching;
import javax.cache.configuration.MutableConfiguration;
import javax.el.ELProcessor;
import javax.el.ELManager;
import javax.el.StandardELContext;
import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;
import java.util.logging.Logger;

public class DistributedCacheClient {
    private static final Logger LOG = Logger.getLogger(DistributedCacheClient.class.getName());
    private final Cache<String, CacheEntry> cache;
    private final RoleResolver roleResolver;
    private final PolicyEngine policyEngine;

    public DistributedCacheClient(CacheManager manager, RoleResolver resolver) {
        MutableConfiguration<String, CacheEntry> config = new MutableConfiguration<>();
        config.setTypes(String.class, CacheEntry.class);
        this.cache = manager.createCache("distributed-store", config);
        this.roleResolver = resolver;
        this.policyEngine = new PolicyEngine();
    }

    public Object get(String principal, String cacheKey) {
        Set<String> roles = roleResolver.resolveRoles(principal);
        CacheEntry entry = cache.get(cacheKey);
        if (entry == null) {
            LOG.fine("Cache miss for key: " + cacheKey);
            return null;
        }
        if (!policyEngine.checkAccess(roles, entry.getAccessPolicy())) {
            LOG.warning("Access denied for principal: " + principal);
            throw new SecurityException("Insufficient privileges");
        }
        return entry.getValue();
    }

    public void put(String principal, String cacheKey, Object value, String accessPolicy) {
        Set<String> roles = roleResolver.resolveRoles(principal);
        if (!roles.contains("cache-writer") && !roles.contains("admin")) {
            throw new SecurityException("Write access denied");
        }
        CacheEntry entry = new CacheEntry(value, accessPolicy, principal);
        cache.put(cacheKey, entry);
        LOG.info("Cache entry stored by: " + principal);
    }

    public static class CacheEntry implements java.io.Serializable {
        private final Object value;
        private final String accessPolicy;
        private final String owner;
        private final long timestamp;

        public CacheEntry(Object value, String accessPolicy, String owner) {
            this.value = value;
            this.accessPolicy = accessPolicy;
            this.owner = owner;
            this.timestamp = System.currentTimeMillis();
        }

        public Object getValue() { return value; }
        public String getAccessPolicy() { return accessPolicy; }
        public String getOwner() { return owner; }
        public long getTimestamp() { return timestamp; }
    }

    public interface RoleResolver {
        Set<String> resolveRoles(String principal);
    }

    public static class PolicyEngine {
        private final ELProcessor elProcessor;

        public PolicyEngine() {
            this.elProcessor = new ELProcessor();
            elProcessor.defineBean("env", new PolicyEnvironment());
        }

        public boolean checkAccess(Set<String> userRoles, String policyExpression) {
            if (policyExpression == null || policyExpression.isEmpty()) {
                return true;
            }
            elProcessor.defineBean("userRoles", userRoles);
            try {
                Object result = elProcessor.eval(policyExpression);
                if (result instanceof Boolean) {
                    return (Boolean) result;
                }
                return false;
            } catch (Exception e) {
                LOG.warning("Policy evaluation failed: " + e.getMessage());
                return false;
            }
        }
    }

    public static class PolicyEnvironment {
        private final Map<String, String> properties;

        public PolicyEnvironment() {
            this.properties = new HashMap<>();
            properties.put("classification", "internal");
            properties.put("region", System.getProperty("app.region", "us-east-1"));
        }

        public String getProperty(String key) {
            return properties.getOrDefault(key, "");
        }

        public boolean isInternalNetwork() {
            return "true".equals(System.getProperty("app.internal", "false"));
        }
    }

    public Map<String, Object> bulkGet(String principal, Set<String> keys) {
        Map<String, Object> results = new HashMap<>();
        Set<String> roles = roleResolver.resolveRoles(principal);
        for (String key : keys) {
            CacheEntry entry = cache.get(key);
            if (entry != null && policyEngine.checkAccess(roles, entry.getAccessPolicy())) {
                results.put(key, entry.getValue());
            }
        }
        return results;
    }

    public boolean evict(String principal, String cacheKey) {
        Set<String> roles = roleResolver.resolveRoles(principal);
        if (!roles.contains("admin")) {
            CacheEntry entry = cache.get(cacheKey);
            if (entry == null || !entry.getOwner().equals(principal)) {
                throw new SecurityException("Cannot evict entries owned by others");
            }
        }
        return cache.remove(cacheKey);
    }
}
